function withRetry<T extends (...args: any[]) => any>(
    fn: T,
    attempts: number,
): (...args: Parameters<T>) => ReturnType<T> {
    return (...args: Parameters<T>): ReturnType<T> => {
        let lastError: unknown
        for (let i = 1; i <= attempts; i++) {
            try {
                return fn(...args)
            } catch (e) {
                lastError = e
                console.log(`  ${i}-urinish muvaffaqiyatsiz`)
            }
        }
        throw lastError
    }
}

let counter = 0
function flaky(value: string): string {
    counter++
    if (counter < 3) throw new Error("xato")
    return `${value} muvaffaqiyatli`
}

